-- Limpeza de `legacy.shipments` — camada `staging` (ADR-0016).
--
-- Uma linha por ocorrência física da **captura mais recente**. Reter capturas
-- antigas (ADR-0037) não significa somá-las: o tratamento olha a última, e as
-- anteriores existem para comparação e reprocessamento.
--
-- Duas saídas por coluna: o valor tratado e o **achado**, que é o código da
-- primeira falha que casa. O valor original permanece acessível em
-- `raw_legacy`, que é imutável.

with captura as (

    select *
    from {{ source('legacy', 'shipments') }}
    where _airbyte_generation_id = coalesce(
        {{ legacy_snapshot_id() }}, (
        select max(_airbyte_generation_id) from {{ source('legacy', 'shipments') }}
    ))

),

-- A limpeza vem **antes** dos achados, e não junto: o achado de rejeição
-- precisa ser conferido contra o valor já convertido, senão uma conversão
-- bem-sucedida esconde a invalidade do resultado dela.
limpo as (

    select
        c.legacy_row_id,
        case
            when btrim(c."id") = '' or btrim(c."id") in ('NULL', 'null', 'N/A', '-', '#N/D', '   ') then null
            else c."id"
        end as "id",
        case
            when btrim(c."shipment_code") = '' or btrim(c."shipment_code") in ('NULL', 'null', 'N/A', '-', '#N/D', '   ') then null
            when c."shipment_code" like '%;%' and (c."order_id" is null or btrim(c."order_id") = '') and (c."carrier_id" is null or btrim(c."carrier_id") = '') then c."shipment_code"
            when c."shipment_code" ~ '(Ã[-¿]|Â[-¿])' and c."shipment_code" !~ '(Ã|Â)[A-ZÁÂÃÉÊÍÓÔÕÚÇ ]' then convert_from(convert_to(c."shipment_code", 'LATIN1'), 'UTF8')
            when c."shipment_code" <> btrim(c."shipment_code") or c."shipment_code" ~ '  ' then regexp_replace(btrim(c."shipment_code"), '\s+', ' ', 'g')
            else c."shipment_code"
        end as "shipment_code",
        c."order_id" as "order_id",
        c."carrier_id" as "carrier_id",
        c."warehouse_id" as "warehouse_id",
        case
            when btrim(c."status") = '' or btrim(c."status") in ('NULL', 'null', 'N/A', '-', '#N/D', '   ') then null
            when btrim(c."status") not in ('created', 'picking', 'dispatched', 'in_transit', 'delivered', 'returned', 'lost') then c."status"
            else c."status"
        end as "status",
        case
            when btrim(c."tracking_code") = '' or btrim(c."tracking_code") in ('NULL', 'null', 'N/A', '-', '#N/D', '   ') then null
            when c."tracking_code" like '%;%' and (c."freight_amount" is null or btrim(c."freight_amount") = '') and (c."shipped_at" is null or btrim(c."shipped_at") = '') then c."tracking_code"
            when c."tracking_code" ~ '(Ã[-¿]|Â[-¿])' and c."tracking_code" !~ '(Ã|Â)[A-ZÁÂÃÉÊÍÓÔÕÚÇ ]' then convert_from(convert_to(c."tracking_code", 'LATIN1'), 'UTF8')
            when c."tracking_code" <> btrim(c."tracking_code") or c."tracking_code" ~ '  ' then regexp_replace(btrim(c."tracking_code"), '\s+', ' ', 'g')
            else c."tracking_code"
        end as "tracking_code",
        case
            when btrim(c."freight_amount") = '' or btrim(c."freight_amount") in ('NULL', 'null', 'N/A', '-', '#N/D', '   ') then null
            when btrim(replace(replace(c."freight_amount", 'R$', ''), ' ', '')) ~ '^-' then c."freight_amount"
            when c."freight_amount" !~ '^-?[0-9]+(\.[0-9]{1,4})?$' and (   c."freight_amount" ~ '^-?(R\$)?\s*[0-9]{1,3}(\.[0-9]{3})*,[0-9]{1,4}$'   or c."freight_amount" ~ '^-?(R\$)?\s*[0-9]+,[0-9]{1,4}$'   or c."freight_amount" ~ '^-?(R\$)?\s*[0-9]{1,3}(,[0-9]{3})+(\.[0-9]{1,4})?$'   or c."freight_amount" ~ '^-?(R\$)?\s*[0-9]+(\.[0-9]{1,4})?$') then case when btrim(replace(replace(c."freight_amount", 'R$', ''), ' ', '')) ~ ',[0-9]{1,4}$' then replace(replace(replace(replace(c."freight_amount", 'R$', ''), ' ', ''), '.', ''), ',', '.') else replace(replace(replace(c."freight_amount", 'R$', ''), ' ', ''), ',', '') end
            when c."freight_amount" !~ '^-?[0-9]+(\.[0-9]{1,4})?$' then c."freight_amount"
            else c."freight_amount"
        end as "freight_amount",
        case
            when btrim(c."shipped_at") = '' or btrim(c."shipped_at") in ('NULL', 'null', 'N/A', '-', '#N/D', '   ') then null
            when case when c."shipped_at" ~ '^[0-9]{4}[-.][0-9]{2}[-.][0-9]{2}'   then not (substring(c."shipped_at" from 6 for 2)::int between 1 and 12 and substring(c."shipped_at" from 9 for 2)::int between 1 and 31 and not (substring(c."shipped_at" from 6 for 2)::int in (4, 6, 9, 11) and substring(c."shipped_at" from 9 for 2)::int > 30) and not (substring(c."shipped_at" from 6 for 2)::int = 2 and substring(c."shipped_at" from 9 for 2)::int > 29) and not (substring(c."shipped_at" from 6 for 2)::int = 2 and substring(c."shipped_at" from 9 for 2)::int = 29 and not (substring(c."shipped_at" from 1 for 4)::int % 4 = 0 and (substring(c."shipped_at" from 1 for 4)::int % 100 <> 0 or substring(c."shipped_at" from 1 for 4)::int % 400 = 0)))) when c."shipped_at" ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$'   then not (substring(c."shipped_at" from 4 for 2)::int between 1 and 12 and substring(c."shipped_at" from 1 for 2)::int between 1 and 31 and not (substring(c."shipped_at" from 4 for 2)::int in (4, 6, 9, 11) and substring(c."shipped_at" from 1 for 2)::int > 30) and not (substring(c."shipped_at" from 4 for 2)::int = 2 and substring(c."shipped_at" from 1 for 2)::int > 29) and not (substring(c."shipped_at" from 4 for 2)::int = 2 and substring(c."shipped_at" from 1 for 2)::int = 29 and not (substring(c."shipped_at" from 7 for 4)::int % 4 = 0 and (substring(c."shipped_at" from 7 for 4)::int % 100 <> 0 or substring(c."shipped_at" from 7 for 4)::int % 400 = 0)))) when c."shipped_at" ~ '^[0-9]{2}/[0-9]{4}$' then true else false end then c."shipped_at"
            when case when c."shipped_at" ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' and (substring(c."shipped_at" from 6 for 2)::int between 1 and 12 and substring(c."shipped_at" from 9 for 2)::int between 1 and 31 and not (substring(c."shipped_at" from 6 for 2)::int in (4, 6, 9, 11) and substring(c."shipped_at" from 9 for 2)::int > 30) and not (substring(c."shipped_at" from 6 for 2)::int = 2 and substring(c."shipped_at" from 9 for 2)::int > 29) and not (substring(c."shipped_at" from 6 for 2)::int = 2 and substring(c."shipped_at" from 9 for 2)::int = 29 and not (substring(c."shipped_at" from 1 for 4)::int % 4 = 0 and (substring(c."shipped_at" from 1 for 4)::int % 100 <> 0 or substring(c."shipped_at" from 1 for 4)::int % 400 = 0)))) then left(c."shipped_at", 10)::date > date '{{ var("as_of_date") }}' else false end then c."shipped_at"
