            when c."shipped_at" ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}' and c."shipped_at" !~ '(Z|[+-][0-9]{2}:?[0-9]{2})$' then (c."shipped_at"::timestamp at time zone 'America/Sao_Paulo')::text
            when c."shipped_at" !~ '^[0-9]{4}[-.][0-9]{2}[-.][0-9]{2}' and c."shipped_at" !~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' and c."shipped_at" !~ '^[0-9]{2}/[0-9]{4}$' then c."shipped_at"
            else c."shipped_at"
        end as "shipped_at",
        case
            when btrim(c."estimated_delivery_at") = '' or btrim(c."estimated_delivery_at") in ('NULL', 'null', 'N/A', '-', '#N/D', '   ') then null
            when case when c."estimated_delivery_at" ~ '^[0-9]{4}[-.][0-9]{2}[-.][0-9]{2}'   then not (substring(c."estimated_delivery_at" from 6 for 2)::int between 1 and 12 and substring(c."estimated_delivery_at" from 9 for 2)::int between 1 and 31 and not (substring(c."estimated_delivery_at" from 6 for 2)::int in (4, 6, 9, 11) and substring(c."estimated_delivery_at" from 9 for 2)::int > 30) and not (substring(c."estimated_delivery_at" from 6 for 2)::int = 2 and substring(c."estimated_delivery_at" from 9 for 2)::int > 29) and not (substring(c."estimated_delivery_at" from 6 for 2)::int = 2 and substring(c."estimated_delivery_at" from 9 for 2)::int = 29 and not (substring(c."estimated_delivery_at" from 1 for 4)::int % 4 = 0 and (substring(c."estimated_delivery_at" from 1 for 4)::int % 100 <> 0 or substring(c."estimated_delivery_at" from 1 for 4)::int % 400 = 0)))) when c."estimated_delivery_at" ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$'   then not (substring(c."estimated_delivery_at" from 4 for 2)::int between 1 and 12 and substring(c."estimated_delivery_at" from 1 for 2)::int between 1 and 31 and not (substring(c."estimated_delivery_at" from 4 for 2)::int in (4, 6, 9, 11) and substring(c."estimated_delivery_at" from 1 for 2)::int > 30) and not (substring(c."estimated_delivery_at" from 4 for 2)::int = 2 and substring(c."estimated_delivery_at" from 1 for 2)::int > 29) and not (substring(c."estimated_delivery_at" from 4 for 2)::int = 2 and substring(c."estimated_delivery_at" from 1 for 2)::int = 29 and not (substring(c."estimated_delivery_at" from 7 for 4)::int % 4 = 0 and (substring(c."estimated_delivery_at" from 7 for 4)::int % 100 <> 0 or substring(c."estimated_delivery_at" from 7 for 4)::int % 400 = 0)))) when c."estimated_delivery_at" ~ '^[0-9]{2}/[0-9]{4}$' then true else false end then c."estimated_delivery_at"
